    new.raw_user_meta_data->>'business_type',
    new.raw_user_meta_data->>'state',
    new.raw_user_meta_data->>'expected_volume',
    new.raw_user_meta_data->>'store_street',
    new.raw_user_meta_data->>'store_city',
    new.raw_user_meta_data->>'store_zip',
    'customer',
    'pending'
  );
  return new;
end;
$$;

-- =============================================================================
-- 3 of 34: 20261008192000_profile_self_update_guard.sql
-- supabase/migrations/20261008192000_profile_self_update_guard.sql, word for word.
-- =============================================================================

-- Customers cannot rewrite licence, EIN, email, role, status, or tier on their
-- own profile. Admins, and SQL run without a session (the owner provisioning
-- script), are unchanged.

create or replace function public.protect_profile_columns()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null or public.is_admin() then
    return new;
  end if;
  new.email := old.email;
  new.status := old.status;
  new.role := old.role;
  new.pricing_tier := old.pricing_tier;
  new.license_no := old.license_no;
  new.ein := old.ein;
  new.resale_cert_no := old.resale_cert_no;
  return new;
end;
$$;

drop trigger if exists a_protect_profile_columns on public.profiles;
create trigger a_protect_profile_columns
  before update on public.profiles
  for each row execute function public.protect_profile_columns();

