) as v(product_id, old_label, new_label)
where vp.product_id = v.product_id
  and lower(vp.variant) = lower(v.old_label)
  and exists (
    select 1 from public.products as p
    where p.id = v.product_id and p.variants ? v.new_label and not p.variants ? v.old_label
  )
  and not exists (
    select 1 from public.product_variant_prices as other
    where other.product_id = v.product_id and lower(other.variant) = lower(v.new_label)
  );

-- One row per product: lower(old label) -> new label.
update public.products as p
set unavailable_variants = (
  select coalesce(jsonb_agg(coalesce(v.renames -> lower(u.label), to_jsonb(u.label)) order by u.ord), '[]'::jsonb)
  from jsonb_array_elements_text(p.unavailable_variants) with ordinality as u(label, ord)
)
from (values
  (12, '{"cookies cream":"Cookies & cream"}'::jsonb),
  (27, '{"aaa4":"AAA 4-pack","aa4":"AA 4-pack","d2":"D 2-pack","aaa2":"AAA 2-pack","aa2":"AA 2-pack","c2":"C 2-pack"}'::jsonb),
  (51, '{"apple jack":"Apple Jacks"}'::jsonb),
  (52, '{"butter flies":"Butterflies"}'::jsonb),
