  (107, '{"13gal":"13 gal","23gal":"23 gal"}'::jsonb),
  (120, '{"20oz":"20 oz","16oz":"16 oz","12oz":"12 oz","8oz":"8 oz"}'::jsonb),
  (150, '{"iphone":"iPhone (Lightning)","type c":"USB-C","iphone to type c":"Lightning to USB-C","type c to type c":"USB-C to USB-C","home charger with type c":"Home charger with USB-C"}'::jsonb),
  (162, '{"almond reg":"Almond, regular","almond king size":"Almond, king size"}'::jsonb),
  (163, '{"yellow reg":"Yellow, regular","yellow share size":"Yellow, share size","chocolate reg":"Chocolate, regular","chocolate king size":"Chocolate, king size"}'::jsonb),
  (164, '{"vanilla reg":"Vanilla, regular","vanilla king size":"Vanilla, king size"}'::jsonb),
  (166, '{"cups regular":"Cups, regular","cups king size":"Cups, king size","white cups reg":"White cups, regular","white cups king size":"White cups, king size","pieces reg":"Pieces, regular","pieces king size":"Pieces, king size","fast break reg":"Fast break, regular","fast break king size":"Fast break, king size"}'::jsonb),
  (169, '{"red reg":"Red, regular","red king size":"Red, king size","wildberry reg":"Wildberry, regular","wildberry king size":"Wildberry, king size","sour reg":"Sour, regular","sour king size":"Sour, king size","blue reg":"Blue, regular","blue king size":"Blue, king size"}'::jsonb),
  (171, '{"milk reg":"Milk, regular","milk king size":"Milk, king size","cookies reg":"Cookies, regular","cookies king":"Cookies, king size","almond reg":"Almond, regular","almond king":"Almond, king size","mr. goodbar reg":"Mr. Goodbar, regular","mr. goodbar king":"Mr. Goodbar, king size"}'::jsonb),
  (183, '{"winter fresh":"Winterfresh"}'::jsonb),
  (201, '{"5-flavors":"5 Flavors"}'::jsonb),
  (212, '{"8lbs":"8 lb","10lbs":"10 lb"}'::jsonb),
  (242, '{"gold king":"Gold king size","menthol king":"Menthol king size","red king":"Red king size"}'::jsonb),
  (243, '{"gold king":"Gold king size","menthol king":"Menthol king size","orange king":"Orange king size","silver king":"Silver king size"}'::jsonb),
  (314, '{"1kg":"1 kg"}'::jsonb),
  (331, '{"aaa2":"AAA 2-pack"}'::jsonb),
  (356, '{"2gal":"2 gal"}'::jsonb),
  (362, '{"m size":"Medium","l size":"Large"}'::jsonb)
) as v(id, renames)
where p.id = v.id
  and exists (
    select 1 from jsonb_array_elements_text(p.unavailable_variants) as u(label)
    where v.renames ? lower(u.label)
  )
  and not exists (
    select 1 from jsonb_each_text(v.renames) as r(old_label, new_label)
    where not p.variants ? r.new_label
  );

